<?php
declare(strict_types=1);
require dirname(__DIR__) . '/bootstrap.php';
$user=require_api_user('guru');if($_SERVER['REQUEST_METHOD']!=='POST')json_response(false,'Metode tidak diizinkan.',null,405);verify_csrf();if(empty($_FILES['photo'])||$_FILES['photo']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Foto belum dipilih atau gagal diunggah.');$file=$_FILES['photo'];if((int)$file['size']>MAX_UPLOAD_SIZE)throw new RuntimeException('Ukuran foto maksimal 2 MB.');$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Foto harus JPG, PNG, atau WEBP.');$type=(string)($_POST['type']??'student');$target=$type==='teacher'?'teachers':'students';$targetId=$type==='teacher'?$user['id']:(string)($_POST['student_id']??'');if($type==='student'){if(!$targetId||!can_access_student($user,$targetId,true))throw new RuntimeException('Siswa tidak valid.');}elseif($type!=='teacher')throw new RuntimeException('Jenis foto tidak valid.');$directory=UPLOAD_PATH.DIRECTORY_SEPARATOR.$target;if(!is_dir($directory)&&!mkdir($directory,0775,true)&&!is_dir($directory))throw new RuntimeException('Folder upload tidak dapat dibuat.');$filename=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$destination=$directory.DIRECTORY_SEPARATOR.$filename;if(!move_uploaded_file($file['tmp_name'],$destination))throw new RuntimeException('Foto gagal disimpan.');$relative='uploads/'.$target.'/'.$filename;$pdo=db();if($type==='student')$pdo->prepare('UPDATE students SET foto_url=?,updated_at=NOW() WHERE id=?')->execute([$relative,$targetId]);else{$pdo->prepare('UPDATE users SET photo_url=?,updated_at=NOW() WHERE id=?')->execute([$relative,$targetId]);$pdo->prepare('UPDATE teacher_profiles SET photo_url=?,updated_at=NOW() WHERE user_id=?')->execute([$relative,$targetId]);}audit_event('photo_uploaded','success',$targetId,['type'=>$type,'path'=>$relative,'mime'=>$mime]);json_response(true,'Foto berhasil diunggah.',['url'=>url($relative)]);

